#include <chrono>
#include <iostream>
#include <queue>
#include <string>
#include <vector>
using namespace std;

class CORASICK_NODE {

  private:
    CORASICK_NODE *links[26] = {
        nullptr}; // this will store next vertices of other characters
    CORASICK_NODE *suffix_link =
        nullptr; // It will help us to fallback to a right place for new
                 // comparison start without more comparison

    CORASICK_NODE *GO_TRANSITION[26] = {nullptr}; // It will take us where to go

    bool visit = false;

    bool end = false;

  public:
    friend class AHO_CORASICK;

    CORASICK_NODE() = default;

    bool contains(char c) { return links[c - 'a'] != nullptr; }

    void putchar(char c, CORASICK_NODE *node) { links[c - 'a'] = node; }

    CORASICK_NODE *movetonextnode(char c) { return links[c - 'a']; }

    bool isEnd() { return end; }

    void setEnd() { end = true; }
};

class AHO_CORASICK {

  private:
    CORASICK_NODE *trie_root;

  public:
    AHO_CORASICK(const vector<string> &str) : trie_root(new CORASICK_NODE) {
        for (const auto &c : str) {
            buildTrie(c);
        }
    }

    void buildTrie(const string &c) {

        if (c.empty()) {
            return;
        }

        CORASICK_NODE *node = trie_root;

        for (size_t i = 0; i < c.length(); ++i) {

            if (!node->contains(c[i])) {
                node->putchar(c[i], new CORASICK_NODE());
            }

            node = node->movetonextnode(c[i]);
        }

        node->setEnd();
    }

    void buildAutomaton() { // Using BFS Traversal , Constructing fully
                            // deterministic automata

        queue<CORASICK_NODE *> que;

        que.push(trie_root);

        trie_root->suffix_link = trie_root;

        for (int i = 0; i < 26; i++) {
            if (trie_root->links[i] != nullptr) {
                trie_root->GO_TRANSITION[i] = trie_root->links[i];
            } else {
                trie_root->GO_TRANSITION[i] = trie_root;
            }
        }

        while (!que.empty()) {

            CORASICK_NODE *parent_node = que.front();
            que.pop();

            for (int i = 0; i < 26; i++) {

                CORASICK_NODE *childnode = parent_node->links[i];
                if (childnode != nullptr) {

                    if (parent_node == trie_root) {
                        childnode->suffix_link = parent_node;
                    } else {

                        CORASICK_NODE *parentsuffix = parent_node->suffix_link;

                        while (parentsuffix != trie_root and
                               parentsuffix->links[i] == nullptr) {
                            parentsuffix = parentsuffix->suffix_link;
                        }

                        if (parentsuffix->links[i] != nullptr) {
                            childnode->suffix_link = parentsuffix->links[i];
                        } else {
                            childnode->suffix_link = trie_root;
                        }
                    }

                    if (childnode->suffix_link and
                        childnode->suffix_link->isEnd()) {
                        childnode->setEnd();
                    }

                    parent_node->GO_TRANSITION[i] = childnode;
                    que.push(childnode);
                } else {
                    parent_node->GO_TRANSITION[i] =
                        parent_node->suffix_link->GO_TRANSITION[i];
                }
            }
        }
    }

    auto MonoExistingStr(const string &inp, const vector<string> &str)
        -> vector<int> { // linear time complexity using DFS Traversal .

        CORASICK_NODE *root = trie_root;

        for (int i = 0; i < inp.length(); i++) {

            root = root->GO_TRANSITION[inp[i] - 'a'];

            CORASICK_NODE *tmp = root;
            while (tmp->visit == false) {
                tmp->visit = true;
                tmp = tmp->suffix_link;
            }
        }

        vector<int> ans;

        for (int j = 0; j < str.size(); j++) {

            CORASICK_NODE *endnode = GetEndNode(str[j]);

            if (endnode->visit == true) {
                ans.push_back(1);
            } else {
                ans.push_back(0);
            }
        }
        return ans;
    }

    CORASICK_NODE *GetEndNode(const string &s) {

        CORASICK_NODE *node = trie_root;
        for (const auto &c : s) {

            node = node->GO_TRANSITION[c - 'a'];
        }

        return node;
    }
};

// Constructing the vector of all patterns to look into the input source. These patterns are made in such a way they don't exist so that we can test the algorithm on extreme scenerios 
std::vector<std::string> get_clean_vector(const string &source) {
    // 1. The forbidden input text

    std::vector<std::string> v;
    v.reserve(1000);

    // Deterministic generation logic
    // We use a simple custom LCG (Linear Congruential Generator) to ensure
    // you get the exact same "random" words every time you run this code.
    unsigned long seed = 12345;
    const char charset[] = "abcdefghijklmnopqrstuvwxyz";

    while (v.size() < 1000) {
        std::string s = "";
        for (int i = 0; i < 5; ++i) { // Fixed size 5 satisfies "average size 5"
            seed = (seed * 1103515245 + 12345) & 0x7FFFFFFF;
            s += charset[seed % 26];
        }

        // Only add if it doesn't exist in source
        if (source.find(s) == std::string::npos) {
            v.push_back(s);
        }
    }
    return v;
}

